int ceph_auth_client_process_ticket(struct ceph_auth_client *ac,
                                    struct ceph_crypto_key *secret,
                                    void **p, void *end)
{
    int ret = -EINVAL;
    void *ticket_start = *p;
    uint32_t type, version;

    if (end - *p < sizeof(type) + sizeof(version))
        goto out;

    type = ceph_decode_32(p);
    version = ceph_decode_32(p);

    if (!ac->ticket_handlers[type]) {
        ret = -ENOTSUPP;
        goto out;
    }

    struct ceph_auth_ticket_handler *handler = ac->ticket_handlers[type];
    struct ceph_auth_ticket ticket;

    ret = handler->decode_ticket(&ticket, p, end);
    if (ret < 0)
        goto out;

    if (ticket.encrypted_blob.length <= 0) {
        ret = -EINVAL;
        goto out;
    }

    struct ceph_crypto_key *decrypted_key = NULL;
    ret = ceph_decrypt_key(secret, &ticket.encrypted_blob, &decrypted_key);
    if (ret < 0)
        goto out;

    if (ticket.expires.tv_sec < ceph_time_now().tv_sec) {
        ret = -ETIMEDOUT;
        goto out_free_key;
    }

    ac->session_key = *decrypted_key;
    ac->ticket_blob = ticket.blob;

    ret = 0;

out_free_key:
    ceph_crypto_key_free(decrypted_key);
out:
    *p = ticket_start;
    return ret;
}

int ceph_auth_client_process_ticket(struct ceph_auth_client *ac,
                                    struct ceph_crypto_key *secret,
                                    void **p, void *end)
{
  int ret = -EINVAL;
  void *ticket_start = *p;
  int type, version;

  if (*p + sizeof(type) > end) {
    goto out;
  }

  type = le32_to_cpu(*(__le32 *)*p);
  *p += sizeof(type);

  if (*p + sizeof(version) > end) {
    goto out;
  }

  version = le32_to_cpu(*(__le32 *)*p);
  *p += sizeof(version);

  struct ceph_auth_ticket_handler *handler = ceph_get_ticket_handler(type, version);
  if (!handler) {
    goto out;
  }

  void *decrypted = NULL;
  ret = handler->decrypt(secret, *p, end, &decrypted);
  if (ret < 0) {
    goto out;
  }

  struct ceph_auth_session_key *session_key;
  session_key = kmalloc(sizeof(*session_key), GFP_NOFS);
  if (!session_key) {
    ret = -ENOMEM;
    goto out_free_decrypted;
  }

  ret = handler->parse_decrypted(decrypted, session_key, ac);
  if (ret < 0) {
    goto out_free_session_key;
  }

  ac->session_key = session_key;
  ac->ticket_blob = kmalloc(ret, GFP_NOFS);
  if (!ac->ticket_blob) {
    ret = -ENOMEM;
    goto out_free_session_key;
  }

  memcpy(ac->ticket_blob, session_key, ret);
  ac->ticket_blob_size = ret;

  ret = 0;
  goto out;

out_free_session_key:
  kfree(session_key);
out_free_decrypted:
  kfree(decrypted);
out:
  if (ret < 0) {
    ceph_auth_client_reset(ac);
  }

  return ret;
}

int ceph_auth_client_process_ticket(struct ceph_auth_client *ac, struct ceph_crypto_key *secret, void **p, void *end) {
    int ret = -EINVAL;
    void *ticket_start = *p;
    uint32_t type, version;
    struct ceph_auth_ticket *ticket = NULL;

    if (*p + sizeof(type) > end) {
        goto out;
    }
    type = le32_to_cpu(*(__le32*)(*p));
    (*p) += sizeof(type);

    if (*p + sizeof(version) > end) {
        goto out;
    }
    version = le32_to_cpu(*(__le32*)(*p));
    (*p) += sizeof(version);

    ticket = kmalloc(sizeof(*ticket), GFP_NOFS);
    if (!ticket) {
        goto out;
    }

    ret = ceph_decode_ticket(type, version, ac, secret, p, end, ticket);
    if (ret < 0) {
        goto out;
    }

    if (ceph_time_now_after(&ticket->expiration, ceph_time_now())) {
        ac->session_key = ticket->session_key;
        ac->ticket_blob = ticket->blob;
        ac->ticket_blob_len = ticket->blob_len;
        ret = 0;
    } else {
        ret = -ETIME;
    }

out:
    if (ret < 0 && ticket) {
        kfree(ticket->blob);
        kfree(ticket);
    }
    *p = ticket_start;
    return ret;
}

int ceph_auth_client_process_ticket(struct ceph_auth_client *ac, struct ceph_crypto_key *secret, void **p, void *end) {
    int err = 0;
    struct ceph_auth_ticket *ticket;
    void *ticket_end;

    // Decode the ticket
    if ((err = ceph_decode_dout(p, end, &ticket)) < 0) {
        return err;
    }
    ticket_end = (void *)((char *)ticket + sizeof(*ticket));

    // Check version and type
    if ((err = ceph_auth_client_get_ticket_handler(ac, ticket->type)) < 0) {
        ceph_free(ticket);
        return err;
    }

    // Decrypt the ticket payload
    if ((err = ceph_crypto_decrypt(secret, &ticket->encrypted, &ticket->decrypted)) < 0) {
        ceph_free(ticket);
        return err;
    }

    // Update session key and ticket blob
    if ((err = ceph_auth_client_update_session_key(ac, &ticket->decrypted)) < 0) {
        ceph_free(ticket);
        return err;
    }

    if ((err = ceph_auth_client_update_ticket_blob(ac, ticket)) < 0) {
        ceph_free(ticket);
        return err;
    }

    ceph_free(ticket);
    return 0;
}

int ceph_auth_client_process_ticket(struct ceph_auth_client *ac, struct ceph_crypto_key *secret, void **p, void *end) {
    int ret = -EINVAL;
    struct ceph_auth_ticket *ticket = NULL;
    struct ceph_ticket_blob *blob = NULL;
    struct ceph_crypto_key *session_key = NULL;
    void *decrypted = NULL;
    size_t decrypted_len = 0;

    ticket = ceph_decode_ticket(p, end);
    if (!ticket) {
        goto out;
    }

    blob = ceph_decode_ticket_blob(p, end);
    if (!blob) {
        goto out;
    }

    session_key = ceph_crypto_key_dup(secret);
    if (!session_key) {
        goto out;
    }

    ret = ceph_decrypt_ticket(blob, session_key, &decrypted, &decrypted_len);
    if (ret < 0) {
        goto out;
    }

    ret = ceph_validate_ticket(ticket, decrypted, decrypted_len);
    if (ret < 0) {
        goto out;
    }

    ac->session_key = session_key;
    ac->ticket_blob = blob;
    ac->ticket = ticket;

    ret = 0;

out:
    if (ret < 0) {
        if (ticket) {
            ceph_decode_put(ticket);
        }
        if (blob) {
            ceph_decode_put(blob);
        }
        if (session_key) {
            ceph_crypto_key_free(session_key);
        }
        if (decrypted) {
            free(decrypted);
        }
    }
    return ret;
}
